                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    label={{
                      value: "Top-1 share",
                      position: "insideBottom",
                      offset: -4,
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Top-3"
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    label={{
                      value: "Top-3 share",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                    }}
                  />
                  <ZAxis type="number" dataKey="z" range={[80, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => [
                      fmtPct(Number(v)),
                      name === "x" ? "Top-1" : name === "y" ? "Top-3" : name,
                    ]}
                    labelFormatter={(_, p) => p?.[0]?.payload?.short ?? ""}
                    content={({ active, payload }) => {
                      if (!active || !payload?.length) return null;
                      const d = payload[0].payload;
                      return (
                        <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs shadow-sm">
                          <p className="font-semibold text-slate-900">
                            {d.lens}
                          </p>
                          <p className="text-slate-600">
                            Top-1 {fmtPct(d.top1Pct)} ({d.top1Label})
                          </p>
                          <p className="text-slate-600">
                            Top-3 {fmtPct(d.top3Pct)}
                          </p>
                          <p className="mt-1 text-slate-400">{d.note}</p>
                        </div>
                      );
                    }}
                  />
                  <Scatter data={lensScatter} fill={ROSE}>
                    {lensScatter.map((l) => (
                      <Cell
                        key={l.short}
                        fill={
                          l.short === "HS issuers"
                            ? AMBER
                            : l.short === "Channels"
                              ? VIOLET
                              : l.short === "ETF flows"
                                ? SKY
                                : l.short === "AI debt"
                                  ? EMERALD
                                  : ROSE
                        }
                      />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Issuer and channel lenses sit high on both axes; the AI-debt bloc
              and IG-calendar lenses are high on top-1 but lack a meaningful
              top-3 ladder (single bloc / theme prints).
            </p>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

