                    }
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) =>
                      ladderMetric === "amountBn" ? `$${v}B` : `${v}%`
                    }
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={56}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [
                      ladderMetric === "amountBn"
                        ? fmtBn(Number(v))
                        : fmtPct(Number(v)),
                      ladderMetric === "amountBn"
                        ? "Issuance"
                        : ladderMetric === "cumulative"
                          ? "Cumulative"
                          : "Share",
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.issuer ?? ""
                    }
                  />
                  <Bar
                    dataKey={
                      ladderMetric === "amountBn"
