                  </PieChart>
                </ResponsiveContainer>
              </div>
              <div className="h-64 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={etfBars}
                    layout="vertical"
                    margin={{ top: 4, right: 8, left: 4, bottom: 4 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      type="number"
                      domain={
                        etfMetric === "flowsBn" ? [0, "auto"] : [0, 100]
                      }
                      tick={{ fontSize: 10 }}
                      tickFormatter={(v) =>
                        etfMetric === "flowsBn" ? `$${v}B` : `${v}%`
                      }
                    />
                    <YAxis
                      type="category"
                      dataKey="ticker"
                      width={72}
                      tick={{ fontSize: 10 }}
                    />
                    <Tooltip
                      formatter={(v) => [
                        etfMetric === "flowsBn"
                          ? fmtBn(Number(v))
                          : fmtPct(Number(v)),
                        etfMetric === "flowsBn" ? "Flows" : "Share",
                      ]}
                    />
                    <Bar
                      dataKey={
                        etfMetric === "flowsBn" ? "flowsBn" : "sharePct"
                      }
                      radius={[0, 4, 4, 0]}
                    >
                      {etfBars.map((r) => (
                        <Cell key={r.ticker} fill={r.fill} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Equity-side concentration: {HEADLINE.top1EtfLabel} alone absorbs
              half of thematic creations ??? a sentiment-capacity meter, not
              issuer proceeds.
            </p>
          </ChartCard>

          <ChartCard
            title="Cross-lens concentration map"
            subtitle="Top-1 vs top-3 share across issuer, stack, channel, ETF, and calendar lenses"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart
                  margin={{ top: 12, right: 16, left: 8, bottom: 12 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Top-1"
                    domain={[0, 60]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    label={{
                      value: "Top-1 share",
                      position: "insideBottom",
                      offset: -4,
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Top-3"
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    label={{
                      value: "Top-3 share",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                    }}
                  />
                  <ZAxis type="number" dataKey="z" range={[80, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => [
                      fmtPct(Number(v)),
                      name === "x" ? "Top-1" : name === "y" ? "Top-3" : name,
                    ]}
                    labelFormatter={(_, p) => p?.[0]?.payload?.short ?? ""}
                    content={({ active, payload }) => {
                      if (!active || !payload?.length) return null;
                      const d = payload[0].payload;
                      return (
                        <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs shadow-sm">
                          <p className="font-semibold text-slate-900">
                            {d.lens}
                          </p>
                          <p className="text-slate-600">
                            Top-1 {fmtPct(d.top1Pct)} ({d.top1Label})
                          </p>
                          <p className="text-slate-600">
                            Top-3 {fmtPct(d.top3Pct)}
                          </p>
                          <p className="mt-1 text-slate-400">{d.note}</p>
                        </div>
                      );
                    }}
                  />
                  <Scatter data={lensScatter} fill={ROSE}>
                    {lensScatter.map((l) => (
                      <Cell
                        key={l.short}
                        fill={
                          l.short === "HS issuers"
                            ? AMBER
                            : l.short === "Channels"
                              ? VIOLET
                              : l.short === "ETF flows"
                                ? SKY
                                : l.short === "AI debt"
                                  ? EMERALD
                                  : ROSE
                        }
                      />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Issuer and channel lenses sit high on both axes; the AI-debt bloc
              and IG-calendar lenses are high on top-1 but lack a meaningful
              top-3 ladder (single bloc / theme prints).
            </p>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

